// Code playground: Attack classifier sederhana (latihan kata kunci)
function classifyAttack(desc) {
  const text = desc.toLowerCase();
  if (text.includes('phish') || text.includes('spear') || text.includes('smishing') || text.includes('vishing')) return 'Phishing';
  if (text.includes('dos') || text.includes('ddos') || text.includes('flood') || text.includes('service unavailable')) return 'DoS/DDoS';
  if (text.includes('mitm') || text.includes('man in the middle') || text.includes('intercept')) return 'MITM';
  if (text.includes('ransom') || text.includes('encrypt') || text.includes('file locked') || text.includes('tebus')) return 'Ransomware';
  return 'Unknown';
}

const samples = [
  'Email phishing meminta login karena akun akan diblokir',
  'Serangan DoS menyebabkan service unavailable selama 30 menit',
  'MITM mengintersep trafik saat pengguna login',
  'Ransomware mengenkripsi file dan menampilkan pesan tebus',
  'Aktivitas aneh tanpa petunjuk kata kunci'
];

for (const s of samples) {
  console.log(s, '=>', classifyAttack(s));
}

// Code playground: Deteksi risiko email berbasis kata kunci (simulasi)
function detectEmailRisk(subject, body) {
  const text = (subject + ' ' + body).toLowerCase();
  let risk = 0;
  if (text.includes('verify') || text.includes('login') || text.includes('password')) risk += 2;
  if (text.includes('urgent') || text.includes('segera') || text.includes('akun akan') || text.includes('diblokir')) risk += 2;
  if (text.includes('free') || text.includes('hadiah') || text.includes('win') || text.includes('pemenang')) risk += 1;
  if (text.includes('wire') || text.includes('transfer') || text.includes('bank') || text.includes('invoice')) risk += 2;
  if (text.includes('unsubscribe') || text.includes('spam')) risk += 1;
  if (text.includes('attachment') || text.includes('lampiran') || text.includes('.exe') || text.includes('link')) risk += 1;

  if (risk >= 6) return 'High';
  if (risk >= 3) return 'Medium';
  return 'Low';
}

const tests = [
  { subject: 'URGENT: Akun akan diblokir', body: 'Verifikasi login password sekarang untuk mencegah kehilangan akses' },
  { subject: 'Info newsletter', body: 'Terima kasih sudah berlangganan. Klik unsubscribe jika tidak ingin menerima email' },
  { subject: 'Pemberitahuan invoice', body: 'Silakan transfer pembayaran sesuai invoice terlampir. Attachment bisa berupa PDF' },
  { subject: 'Hadiah Free Win!', body: 'Anda pemenang. Klik link untuk klaim hadiah sekarang' }
];

tests.forEach(t => {
  console.log(t.subject, '=> risk:', detectEmailRisk(t.subject, t.body));
});
